Interface PaymentMethod
  Method Charge(amount As Integer) As Integer;
EndInterface

Class Cash Implements PaymentMethod
  Method Charge(amount As Integer) As Integer
    Return amount;
  EndMethod
EndClass

Class Card Implements PaymentMethod
  Method Charge(amount As Integer) As Integer
    Return amount + amount * 5 Div 100;
  EndMethod
EndClass

Class Voucher Implements PaymentMethod
  Private Define available As Integer;

  Method Constructor(balance As Integer)
    This.available <- balance;
  EndMethod

  Method Charge(amount As Integer) As Integer
    If amount > This.available Then
      Return This.available;
    EndIf
    Return amount;
  EndMethod
EndClass

Subroutine ChargeWith<T: PaymentMethod>(payment As T, amount As Integer) As Integer
  Return payment.Charge(amount);
EndSubroutine

Algorithm Till
  Define payment, amount As Integer;
  Read payment;
  Read amount;
  If payment = 1 Then
    Write ChargeWith(New Cash(), amount);
  Else
    If payment = 2 Then
      Write ChargeWith(New Card(), amount);
    Else
      Write ChargeWith(New Voucher(15), amount);
    EndIf
  EndIf
EndAlgorithm

